import React, { useEffect, useState } from "react";

function EnhancedSearch() {
  const [buses, setBuses] = useState([]);
  const [filteredBuses, setFilteredBuses] = useState([]);
  const [source, setSource] = useState("");
  const [destination, setDestination] = useState("");
  const [sortOption, setSortOption] = useState("");
  const [filterType, setFilterType] = useState("All");
  const [showFilters, setShowFilters] = useState(true);

  const popularRoutes = [
    { source: "Lucknow", destination: "Kanpur" },
    { source: "Varanasi", destination: "Prayagraj" },
    { source: "Gorakhpur", destination: "Lucknow" },
    { source: "Agra", destination: "Lucknow" },
  ];

  // Fetch buses
  useEffect(() => {
    fetch("http://localhost:4000/api/buses")
      .then((res) => res.json())
      .then((data) => {
        setBuses(data);
        setFilteredBuses(data);
      })
      .catch((err) => console.error(err));
  }, []);

  const cheapestFare =
    filteredBuses.length > 0
      ? Math.min(...filteredBuses.map((bus) => bus.fare))
      : null;

  let displayedBuses = [...filteredBuses];

  if (filterType !== "All") {
    displayedBuses = displayedBuses.filter((bus) => bus.type === filterType);
  }

  if (sortOption === "fareLow") {
    displayedBuses.sort((a, b) => a.fare - b.fare);
  }

  if (sortOption === "fareHigh") {
    displayedBuses.sort((a, b) => b.fare - a.fare);
  }

  if (sortOption === "timeEarly") {
    displayedBuses.sort(
      (a, b) =>
        new Date(`1970/01/01 ${a.time}`) - new Date(`1970/01/01 ${b.time}`)
    );
  }

  const handleSearch = async () => {
    try {
      const res = await fetch(
        `http://localhost:4000/api/buses/search?source=${source}&destination=${destination}`
      );
      const data = await res.json();
      setFilteredBuses(data);
    } catch (err) {
      console.error(err);
    }
  };

  const selectRoute = (src, dest) => {
    setSource(src);
    setDestination(dest);

    const results = buses.filter((bus) => {
      return (
        bus.route?.from?.toLowerCase().includes(src.toLowerCase()) &&
        bus.route?.to?.toLowerCase().includes(dest.toLowerCase())
      );
    });

    setFilteredBuses(results);
  };

  const swapLocations = () => {
    const temp = source;
    setSource(destination);
    setDestination(temp);
  };

  const resetSearch = () => {
    setSource("");
    setDestination("");
    setFilteredBuses(buses);
    setSortOption("");
    setFilterType("All");
  };

  return (
    <div className="min-h-screen" style={{ background: "linear-gradient(135deg, #0f172a 0%, #1e3a8a 100%)" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Poppins:wght@500;600;700;800&family=Inter:wght@400;500;600&display=swap');

        * {
          font-family: 'Inter', sans-serif;
        }

        h1, h2, h3, .font-display {
          font-family: 'Poppins', sans-serif;
          font-weight: 700;
        }

        input, select, button {
          font-family: 'Inter', sans-serif;
        }

        .search-input {
          background: rgba(255, 255, 255, 0.95);
          border: 2px solid transparent;
          transition: all 0.3s ease;
        }

        .search-input:focus {
          outline: none;
          border-color: #06b6d4;
          background: white;
          box-shadow: 0 0 0 3px rgba(6, 182, 212, 0.1);
        }

        .btn-primary {
          background: linear-gradient(135deg, #06b6d4 0%, #0891b2 100%);
          transition: all 0.3s ease;
          font-weight: 600;
        }

        .btn-primary:hover {
          transform: translateY(-2px);
          box-shadow: 0 10px 25px rgba(6, 182, 212, 0.3);
        }

        .btn-secondary {
          background: rgba(255, 255, 255, 0.95);
          transition: all 0.3s ease;
          font-weight: 600;
        }

        .btn-secondary:hover {
          transform: translateY(-2px);
          box-shadow: 0 10px 25px rgba(0, 0, 0, 0.15);
          background: white;
        }

        .route-btn {
          background: white;
          transition: all 0.3s ease;
          border: 2px solid transparent;
          position: relative;
          overflow: hidden;
        }

        .route-btn:hover {
          border-color: #06b6d4;
          transform: translateY(-3px);
          box-shadow: 0 12px 30px rgba(6, 182, 212, 0.2);
        }

        .route-btn::before {
          content: '';
          position: absolute;
          top: 0;
          left: -100%;
          width: 100%;
          height: 100%;
          background: linear-gradient(90deg, transparent, rgba(6, 182, 212, 0.1));
          transition: left 0.5s ease;
        }

        .route-btn:hover::before {
          left: 100%;
        }

        .bus-card {
          background: white;
          transition: all 0.3s ease;
          border: 2px solid transparent;
          animation: slideUp 0.5s ease forwards;
          opacity: 0;
        }

        .bus-card:nth-child(1) { animation-delay: 0.1s; }
        .bus-card:nth-child(2) { animation-delay: 0.2s; }
        .bus-card:nth-child(3) { animation-delay: 0.3s; }
        .bus-card:nth-child(4) { animation-delay: 0.4s; }
        .bus-card:nth-child(5) { animation-delay: 0.5s; }

        @keyframes slideUp {
          from {
            opacity: 0;
            transform: translateY(20px);
          }
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }

        .bus-card:hover {
          transform: translateY(-4px);
          border-color: #06b6d4;
          box-shadow: 0 20px 40px rgba(6, 182, 212, 0.15);
        }

        .cheapest-badge {
          background: linear-gradient(135deg, #10b981 0%, #059669 100%);
          animation: pulse 2s infinite;
        }

        @keyframes pulse {
          0%, 100% {
            box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.7);
          }
          50% {
            box-shadow: 0 0 0 10px rgba(16, 185, 129, 0);
          }
        }

        .filter-section {
          transition: all 0.3s ease;
          background: white;
          border-radius: 12px;
          box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
        }

        .filter-select {
          background: linear-gradient(to right, white 0%, white 95%, #e5e7eb 95%);
          border: 2px solid #e5e7eb;
          transition: all 0.3s ease;
          cursor: pointer;
        }

        .filter-select:focus {
          outline: none;
          border-color: #06b6d4;
          box-shadow: 0 0 0 3px rgba(6, 182, 212, 0.1);
        }

        .filter-select:hover {
          border-color: #06b6d4;
        }

        .swap-btn {
          background: rgba(255, 255, 255, 0.95);
          border: 2px solid rgba(255, 255, 255, 0.3);
          color: #06b6d4;
          font-size: 20px;
          transition: all 0.3s ease;
          cursor: pointer;
        }

        .swap-btn:hover {
          border-color: #06b6d4;
          background: white;
          transform: rotate(180deg);
        }

        .header-gradient {
          background: linear-gradient(180deg, rgba(15, 23, 42, 0.8) 0%, rgba(30, 58, 138, 0.8) 100%);
          backdrop-filter: blur(10px);
        }

        .empty-state {
          text-align: center;
          padding: 60px 20px;
        }

        .empty-state-icon {
          font-size: 60px;
          margin-bottom: 20px;
          opacity: 0.5;
        }

        .badge-type {
          display: inline-block;
          padding: 4px 12px;
          border-radius: 20px;
          font-size: 12px;
          font-weight: 600;
          margin-top: 8px;
        }

        .badge-ac {
          background: rgba(6, 182, 212, 0.1);
          color: #0891b2;
        }

        .badge-volvo {
          background: rgba(139, 92, 246, 0.1);
          color: #7c3aed;
        }

        .badge-ordinary {
          background: rgba(f59e0b, 0.1);
          color: #d97706;
        }

        .info-row {
          display: flex;
          align-items: center;
          gap: 8px;
          color: #6b7280;
          margin: 6px 0;
          font-size: 14px;
        }

        .info-icon {
          font-size: 16px;
          width: 20px;
          text-align: center;
        }

        .price-section {
          text-align: right;
        }

        .price-value {
          font-size: 28px;
          font-weight: 800;
          background: linear-gradient(135deg, #06b6d4 0%, #0891b2 100%);
          -webkit-background-clip: text;
          -webkit-text-fill-color: transparent;
          background-clip: text;
        }

        .track-btn {
          background: linear-gradient(135deg, #06b6d4 0%, #0891b2 100%);
          transition: all 0.3s ease;
          margin-top: 10px;
          font-weight: 600;
        }

        .track-btn:hover {
          transform: translateY(-2px);
          box-shadow: 0 8px 20px rgba(6, 182, 212, 0.3);
        }

        .mobile-toggle {
          display: none;
        }

        @media (max-width: 768px) {
          .mobile-toggle {
            display: block;
          }

          .filter-section {
            display: none;
          }

          .filter-section.active {
            display: block;
            margin-bottom: 20px;
          }

          .search-container {
            flex-direction: column;
          }

          .main-layout {
            flex-direction: column;
          }

          .filter-section {
            width: 100%;
          }

          .results-section {
            width: 100%;
          }
        }
      `}</style>

      {/* Header */}
      <div className="header-gradient">
        <div className="max-w-7xl mx-auto px-6 py-8">
          <div className="mb-6">
            <h1 className="text-4xl font-display text-white mb-2">🚌 IBTS</h1>
            <p className="text-cyan-200">Find and your perfect journey</p>
          </div>

          {/* Search Bar */}
          <div className="flex gap-3 flex-wrap">
            <input
              placeholder="From (e.g., Lucknow)"
              value={source}
              onChange={(e) => setSource(e.target.value)}
              className="search-input px-4 py-3 rounded-lg flex-1 min-w-[200px]"
            />

            <button onClick={swapLocations} className="swap-btn px-3 py-3 rounded-lg">
              ⇄
            </button>

            <input
              placeholder="To (e.g., Kanpur)"
              value={destination}
              onChange={(e) => setDestination(e.target.value)}
              className="search-input px-4 py-3 rounded-lg flex-1 min-w-[200px]"
            />

            <button
              onClick={handleSearch}
              className="btn-primary text-white px-6 py-3 rounded-lg"
            >
              🔍 Search
            </button>

            <button
              onClick={resetSearch}
              className="btn-secondary px-6 py-3 rounded-lg text-gray-700"
            >
              ↻ Reset
            </button>
          </div>
        </div>
      </div>

      {/* Popular Routes */}
      <div className="max-w-7xl mx-auto px-6 py-10">
        <h2 className="text-2xl font-display text-white mb-5">🔥 Popular Routes</h2>

        <div className="flex gap-4 justify-start flex-wrap">
          {popularRoutes.map((route, index) => (
            <button
              key={index}
              onClick={() => selectRoute(route.source, route.destination)}
              className="route-btn px-6 py-3 rounded-lg shadow-md font-semibold text-gray-800"
            >
              {route.source} → {route.destination}
            </button>
          ))}
        </div>
      </div>

      {/* Main Content */}
      <div className="max-w-7xl mx-auto px-6 pb-10 main-layout flex gap-6">
        {/* Filter Panel */}
        <div
          className={`filter-section ${showFilters ? "active" : ""} ${
            showFilters ? "w-64" : "hidden"
          }`}
        >
          <div className="p-6">
            <h2 className="text-xl font-display text-gray-900 mb-6">Filters</h2>

            <div className="mb-6">
              <label className="block mb-2 font-semibold text-gray-700 text-sm">
                Bus Type
              </label>
              <select
                value={filterType}
                onChange={(e) => setFilterType(e.target.value)}
                className="filter-select p-3 w-full rounded-lg"
              >
                <option value="All">All Types</option>
                <option value="AC">AC</option>
                <option value="Ordinary">Ordinary</option>
                <option value="Volvo">Volvo</option>
              </select>
            </div>

            <div>
              <label className="block mb-2 font-semibold text-gray-700 text-sm">
                Sort By
              </label>
              <select
                value={sortOption}
                onChange={(e) => setSortOption(e.target.value)}
                className="filter-select p-3 w-full rounded-lg"
              >
                <option value="">No Sorting</option>
                <option value="fareLow">Fare: Low → High</option>
                <option value="fareHigh">Fare: High → Low</option>
                <option value="timeEarly">Early Departure</option>
              </select>
            </div>
          </div>
        </div>

        {/* Bus Results */}
        <div className="flex-1 results-section">
          {displayedBuses.length > 0 ? (
            <div className="space-y-4">
              {displayedBuses.map((bus) => (
                <div
                  key={bus._id}
                  className={`bus-card p-6 rounded-xl shadow-lg flex justify-between items-center ${
                    bus.fare === cheapestFare
                      ? "border-2 border-green-500 bg-gradient-to-br from-green-50 to-white"
                      : ""
                  }`}
                >
                  <div className="flex-1">
                    <h2 className="text-xl font-display text-gray-900 mb-3">
                      {bus.name}
                    </h2>

                    <div className="space-y-2">
                      <div className="info-row">
                        <span className="info-icon">🚏</span>
                        <span className="font-semibold text-gray-800">
                          {bus.route?.from} <span className="text-cyan-500">→</span> {bus.route?.to}
                        </span>
                      </div>

                      <div className="info-row">
                        <span className="info-icon">🕒</span>
                        <span>Departs at {bus.time}</span>
                      </div>

                      <div className="flex gap-2 items-center mt-3">
                        <span className={`badge-type badge-${bus.type?.toLowerCase()}`}>
                          {bus.type}
                        </span>
                        {bus.fare === cheapestFare && (
                          <span className="cheapest-badge text-white text-xs px-3 py-1 rounded-full font-semibold">
                            ⭐ Best Price
                          </span>
                        )}
                      </div>
                    </div>
                  </div>

                  <div className="price-section ml-6">
                    <p className="price-value">₹{bus.fare}</p>
                    <button className="track-btn text-white px-5 py-2 rounded-lg w-full">
                      🎫 Book Now
                    </button>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="empty-state bg-white rounded-xl shadow-lg">
              <div className="empty-state-icon">🚫</div>
              <h3 className="text-xl font-display text-gray-900 mb-2">No buses found</h3>
              <p className="text-gray-600">Try searching for different routes or dates</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default EnhancedSearch;
